kubectl run egress-check --rm -i --restart=Never --image=curlimages/curl:8.10.1 -- sh -c \
  'curl -sS -o /dev/null -w "docker hub: %{http_code}\n" https://registry-1.docker.io/v2/ ;
   curl -sS -o /dev/null -w "ghcr: %{http_code}\n" https://ghcr.io/v2/ ;
   curl -sS -o /dev/null -w "cloudflare: %{http_code}\n" https://www.cloudflare.com/'
